import java.util.*;
import java.io.*;

public class Main {
    static final int Lg = 18;
    static final int Tw = 1 << Lg;
    static final int Max = Tw + 10;
    static int[][] Ans = new int[Max][Lg + 3];
    static int[] tmp = new int[Lg + 3];
    static int[] tmp2 = new int[Lg + 3];
    static int[] fac = new int[Max];
    static int[] ifac = new int[Max];
    static int N, n, mod;
    static List<Integer> positions = new ArrayList<>();

    static int fast_pow(int base, int exp) {
        int result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (int) ((long) result * base % mod);
            base = (int) ((long) base * base % mod);
            exp >>= 1;
        }
        return result;
    }

    static void combine_add(int[] a, int[] b) {
        for (int i = 0; i <= N; i++) {
            a[i] = (a[i] + b[i]) % mod;
        }
    }

    static void combine_subtract(int[] a, int[] b) {
        for (int i = 0; i <= N; i++) {
            a[i] = (a[i] - b[i]) % mod;
            if (a[i] < 0) a[i] += mod;
        }
    }

    static void convolve(int[] res, int[] a, int[] b) {
        Arrays.fill(tmp, 0);
        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= i; j++) {
                tmp[i] = (int) ((tmp[i] + (long) a[j] * b[i - j]) % mod);
            }
        }
        System.arraycopy(tmp, 0, res, 0, N + 1);
    }

    static void forward_transform(int[][] a) {
        for (int i = 0; i < N; i++) {
            for (int msk = n; msk >= 0; msk--) {
                if (((msk >> i) & 1) == 1) {
                    combine_add(a[msk], a[msk ^ (1 << i)]);
                }
            }
        }
    }

    static void inverse_transform(int[][] a) {
        for (int i = 0; i < N; i++) {
            for (int msk = n; msk >= 0; msk--) {
                if (((msk >> i) & 1) == 1) {
                    combine_subtract(a[msk], a[msk ^ (1 << i)]);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int original_n = 0;
        int K = 0;
        mod = 0;
        if (sc.hasNextInt()) {
            n = sc.nextInt();
            original_n = n;
        }
        if (sc.hasNextInt()) {
            K = sc.nextInt();
        }
        if (sc.hasNextInt()) {
            mod = sc.nextInt();
        }
        int total = fast_pow(K, n);
        if ((n & 1) == 1) {
            System.out.println(total);
            return;
        }
        N = Integer.bitCount(n);
        for (int i = 0; i < Lg; i++) {
            if (((n >> i) & 1) == 1) {
                positions.add(i);
            }
        }
        n = (1 << N) - 1;
        fac[0] = 1;
        for (int i = 1; i < Max; i++) {
            fac[i] = (int) ((long) i * fac[i - 1] % mod);
        }
        ifac[Max - 1] = fast_pow(fac[Max - 1], mod - 2);
        for (int i = Max - 2; i >= 0; i--) {
            ifac[i] = (int) (((long) (i + 1) * ifac[i + 1]) % mod);
        }
        for (int i = 0; i <= n; i++) {
            int val = 0;
            for (int j = 0; j < N; j++) {
                if (((i >> j) & 1) == 1) {
                    val += (1 << positions.get(j));
                }
            }
            Ans[i][Integer.bitCount(i)] = ifac[val];
        }
        forward_transform(Ans);
        for (int i = 0; i <= n; i++) {
            int K_copy = K;
            Arrays.fill(tmp2, 0);
            tmp2[0] = 1;
            while (K_copy > 0) {
                if ((K_copy & 1) == 1) {
                    convolve(tmp2, tmp2, Ans[i]);
                }
                convolve(Ans[i], Ans[i], Ans[i]);
                K_copy >>= 1;
            }
            System.arraycopy(tmp2, 0, Ans[i], 0, N + 1);
        }
        inverse_transform(Ans);
        total = (int) ((total - (long) Ans[n][N] * fac[original_n]) % mod);
        if (total < 0) total += mod;
        System.out.println(total);
    }
}

